import { readFile, writeFile } from 'node:fs/promises';

const sourceFiles = [
  'src/app/00-config-state.js',
  'src/app/01-history.js',
  'src/app/02-file-path-records.js',
  'src/app/03-project-preview-service-worker.js',
  'src/app/04-models-entry-utils.js',
  'src/app/05-reference-resolution.js',
  'src/app/06-virtual-assets.js',
  'src/app/07-preview-editor.js',
  'src/app/08-layout-preview-controls.js',
  'src/app/09-import-export-theme.js',
  'src/app/10-editor-mode-assets.js',
  'src/app/11-explorer-tabs.min.js',
  'src/app/12-mobile-init.js',
  'src/app/13-about-panel.js',
  'src/app/14-cookies-legal.js',
];

const sections = await Promise.all(sourceFiles.map(async (file) => {
  const source = await readFile(file, 'utf8');
  return `\n/* ---- ${file} ---- */\n${source.trim()}\n;`;
}));

const banner = '/* Generated by build-app-bundle.mjs. Edit src/app/*, then run: node build-app-bundle.mjs */\n';
await writeFile('app.bundle.js', banner + sections.join('\n'), 'utf8');
console.log(`Built app.bundle.js from ${sourceFiles.length} source files.`);
